package com.smartgrading.backend.repository;
import com.smartgrading.backend.entity.StudentAnswer; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param;
public interface StudentAnswerRepository extends JpaRepository<StudentAnswer,Integer> { List<StudentAnswer> findBySubmissionId(Integer submissionId); boolean existsBySubmissionIdAndQuestionId(Integer submissionId,Integer questionId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from StudentAnswer a where a.id=:id") Optional<StudentAnswer> findLockedById(@Param("id") Integer id); }
